head.b:skin:
/* ==========================================================================
   MEIWATV - UNIFIED THEATER LIVE STREAMING PORTAL
   ========================================================================== */
:root {
  --bg-dark: #070a10;
  --bg-card: #0e1422;
  --bg-card-hover: #162035;
  --bg-surface: #121929;
  --bg-header: #05080e;

  --primary-green: #10b981;
  --primary-neon: #00eb1f;
  --primary-glow: rgba(16, 185, 129, 0.35);

  --accent-gold: #ffe400;
  --accent-red: #ef4444;
  --accent-red-glow: rgba(239, 68, 68, 0.4);

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(16, 185, 129, 0.5);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Outfit', sans-serif;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-main);
  font-size: 14px;
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

/* TOP NAVBAR */
.site-header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-subtle);
  position: sticky;
  top: 0;
  z-index: 1000;
  backdrop-filter: blur(12px);
}

.nav-container {
  max-width: 1560px;
  margin: 0 auto;
  padding: 0 16px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.brand-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #101726, #1c2840);
  padding: 6px 12px;
  border-radius: 12px;
  border: 1px solid var(--border-subtle);
  text-decoration: none;
  flex-shrink: 0;
}
.brand-logo:hover {
  border-color: var(--primary-green);
  box-shadow: 0 4px 20px var(--primary-glow);
}
.brand-logo-img {
  height: 34px;
  width: auto;
  object-fit: contain;
}

/* Header Navigation Tabs */
.nav-menu-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.nav-menu-links::-webkit-scrollbar {
  display: none;
}

.nav-item-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 700;
  padding: 7px 12px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.nav-item-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
}
.nav-item-btn.active {
  color: #000 !important;
  background: var(--primary-green) !important;
  font-weight: 800;
  box-shadow: 0 2px 10px var(--primary-glow);
}
.nav-item-btn.btn-nav-live.active {
  color: #fff !important;
  background: var(--accent-red) !important;
  box-shadow: 0 2px 12px var(--accent-red-glow);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.btn-saweria-top {
  background: linear-gradient(135deg, #ffbe0b, #fb5607);
  color: #000 !important;
  font-weight: 800;
  font-size: 12px;
  padding: 6px 12px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.btn-apk-top {
  background: var(--bg-surface);
  color: var(--primary-green) !important;
  border: 1px solid var(--primary-green);
  font-weight: 700;
  font-size: 12px;
  padding: 5px 12px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.btn-apk-top:hover {
  background: var(--primary-green);
  color: #000 !important;
}

/* SPONSOR BANNER */
.adsterra-banner-container {
  max-width: 1560px;
  margin: 10px auto 0 auto;
  padding: 0 16px;
}
.adsterra-wrapper-box {
  background: var(--bg-surface);
  border: 1px dashed rgba(16, 185, 129, 0.3);
  border-radius: var(--radius-md);
  padding: 6px 14px;
  text-align: center;
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* MAIN UNIFIED THEATER WORKSPACE */
.main-theater-container {
  max-width: 1560px;
  margin: 12px auto 30px auto;
  padding: 0 16px;
}

/* 2-COLUMN GRID: LEFT PLAYER (68%) + RIGHT INTERACTIVE PLAYLIST (32%) */
.unified-theater-grid {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 16px;
  align-items: stretch;
}
@media (max-width: 1100px) {
  .unified-theater-grid {
    grid-template-columns: 1fr;
  }
}

/* LEFT: THEATER VIDEO PLAYER BOX */
.theater-player-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.player-top-bar {
  background: #090e18;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  flex-wrap: wrap;
  gap: 10px;
}
.player-match-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
}
.live-indicator {
  background: rgba(239, 68, 68, 0.15);
  color: var(--accent-red);
  border: 1px solid rgba(239, 68, 68, 0.3);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.player-server-group {
  display: flex;
  align-items: center;
  gap: 5px;
}
.btn-server {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.btn-server:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.3);
}
.btn-server.active {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
  font-weight: 800;
}

/* 16:9 VIDEO CONTAINER */
.video-container-169 {
  position: relative;
  width: 100%;
  padding-top: 56.25%;
  background: #000;
  overflow: hidden;
}
.video-container-169 video,
.video-container-169 iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  background: #000;
}

.player-stage-screen {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, #10192e 0%, #060911 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
  z-index: 10;
}
.player-stage-league {
  color: var(--primary-green);
  font-weight: 800;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}
.player-stage-title {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 6px;
  max-width: 90%;
}
.player-stage-time {
  color: var(--text-muted);
  font-size: 13px;
  margin-bottom: 18px;
}
.btn-play-stream-huge {
  background: linear-gradient(135deg, var(--primary-green), #059669);
  color: #000;
  font-size: 14.5px;
  font-weight: 800;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  box-shadow: 0 4px 25px var(--primary-glow);
  transition: var(--transition);
}
.btn-play-stream-huge:hover {
  transform: scale(1.05);
  background: var(--primary-neon);
  box-shadow: 0 6px 30px rgba(0, 235, 31, 0.5);
}

/* PLAYER BOTTOM INFO BAR */
.player-match-detail-bar {
  background: #090e18;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-subtle);
  gap: 12px;
  flex-wrap: wrap;
}
.detail-match-teams {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 14px;
}
.detail-team-logo {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.detail-score-pill {
  background: #000;
  color: var(--accent-gold);
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 13.5px;
  padding: 2px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 228, 0, 0.3);
}
.btn-open-source {
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid var(--primary-green);
  color: var(--primary-green);
  padding: 5px 12px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  cursor: pointer;
}
.btn-open-source:hover {
  background: var(--primary-green);
  color: #000;
}

/* RIGHT: INTERACTIVE PLAYLIST & SCHEDULE PANEL */
.interactive-playlist-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  height: 100%;
  min-height: 520px;
  max-height: 720px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.playlist-header-bar {
  background: #090e18;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.playlist-header-title {
  font-size: 13.5px;
  font-weight: 800;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 6px;
}
.playlist-counter-badge {
  background: var(--accent-red);
  color: #fff;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 800;
}

.playlist-search-wrap {
  padding: 8px 12px;
  background: #0a0f1c;
  border-bottom: 1px solid var(--border-subtle);
  position: relative;
}
.playlist-search-input {
  width: 100%;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: #fff;
  font-size: 12.5px;
  padding: 6px 12px 6px 32px;
  border-radius: var(--radius-full);
  outline: none;
}
.playlist-search-input:focus {
  border-color: var(--primary-green);
  box-shadow: 0 0 8px var(--primary-glow);
}
.playlist-search-icon {
  position: absolute;
  left: 22px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
  font-size: 12px;
}

.playlist-scroll-area {
  padding: 8px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

/* CATEGORY DIVIDER INSIDE PLAYLIST */
.playlist-category-divider {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px 4px 10px;
  margin-top: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.playlist-divider-title {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  color: var(--primary-green);
  display: flex;
  align-items: center;
  gap: 6px;
}
.playlist-divider-count {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: var(--radius-full);
}

/* MATCH CARD ROW IN PLAYLIST */
.match-row-item {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 9px 12px;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.match-row-item:hover, .match-row-item.active {
  background: var(--bg-card-hover);
  border-color: var(--primary-green);
  transform: translateX(2px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
}

.match-row-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}
.match-row-league {
  color: var(--primary-green);
  font-weight: 700;
  max-width: 65%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.match-row-time {
  font-size: 10.5px;
  color: var(--text-muted);
}

.match-row-teams-grid {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.team-entry {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  font-size: 12.5px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.team-entry.away {
  justify-content: flex-end;
  text-align: right;
}
.team-mini-logo {
  width: 20px;
  height: 20px;
  object-fit: contain;
  flex-shrink: 0;
}

.match-row-score-badge {
  background: #000;
  color: var(--accent-gold);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 228, 0, 0.25);
  flex-shrink: 0;
}
.match-row-vs-badge {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

/* HIDE UNWANTED BLOGGER STUFF */
.post-hidden-meta,
.event-link-preview,
.match-source-link {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

