// 1. SPORT CATEGORY METADATA HELPER function getSportCategoryMeta(catString, title, league) { const text = ((catString || '') + ' ' + (title || '') + ' ' + (league || '')).toLowerCase(); if (text.includes('basket') || text.includes('bóng rổ') || text.includes('nba') || text.includes('wnba') || text.includes('vba') || text.includes('baloncesto') || text.includes('bundesliga')) { return { icon: '🏀', name: 'Bola Basket', key: 'basketball' }; } if (text.includes('badminton') || text.includes('bulu tangkis') || text.includes('cầu lông') || text.includes('bwf')) { return { icon: '🏸', name: 'Bulu Tangkis', key: 'badminton' }; } if (text.includes('tenis') || text.includes('tennis') || text.includes('atp') || text.includes('wta') || text.includes('davis cup')) { return { icon: '🎾', name: 'Tenis', key: 'tennis' }; } if (text.includes('voli') || text.includes('volleyball') || text.includes('bóng chuyền')) { return { icon: '🏐', name: 'Bola Voli', key: 'volleyball' }; } if (text.includes('esport') || text.includes('dota') || text.includes('league of legends') || text.includes('crossfire') || text.includes('cs2') || text.includes('csgo') || text.includes('pubg') || text.includes('lcs') || text.includes('lec') || text.includes('lit') || text.includes('vcs') || text.includes('lpl') || text.includes('gaming') || text.includes('pgl') || text.includes('starladder') || text.includes('cct') || text.includes('hyperx') || text.includes('nodwin') || text.includes('rift')) { return { icon: '🎮', name: 'Esports & Gaming', key: 'esports' }; } return { icon: '⚽', name: 'Sepak Bola', key: 'football' }; }
