// Filter Matches based on current category tab and search query let filtered = allLoadedMatches.filter(m => { const sportMeta = getSportCategoryMeta(m.sportCategory || '', m.title || '', m.league || ''); const isLive = m.status === 1;
if (currentCategoryFilter === 'live') { if (!isLive) return false; } else if (currentCategoryFilter !== 'all') { if (sportMeta.key !== currentCategoryFilter) return false; }
if (currentSearchKeyword.trim() !== '') { const query = currentSearchKeyword.toLowerCase().trim(); const searchTarget = ((m.title || '') + ' ' + (m.homeTeam || '') + ' ' + (m.awayTeam || '') + ' ' + (m.league || '')).toLowerCase(); if (!searchTarget.includes(query)) return false; }
return true; });
const titlesMap = { live: { icon: '🔴', title: 'Pertandingan Sedang LIVE' }, football: { icon: '⚽', title: 'Jadwal & Live Sepak Bola' }, basketball: { icon: '🏀', title: 'Jadwal & Live Bola Basket' }, badminton: { icon: '🏸', title: 'Jadwal & Live Bulu Tangkis' }, tennis: { icon: '🎾', title: 'Jadwal & Live Tenis' }, volleyball: { icon: '🏐', title: 'Jadwal & Live Bola Voli' }, esports: { icon: '🎮', title: 'Jadwal & Live Esports' }, all: { icon: '🌐', title: 'Semua Jadwal Olahraga' } };
const currentMeta = titlesMap[currentCategoryFilter] || { icon: '🏆', title: 'Jadwal Olahraga' }; if (playlistIcon) playlistIcon.textContent = currentMeta.icon; if (playlistLabel) playlistLabel.textContent = currentMeta.title; if (playlistTotalCount) playlistTotalCount.textContent = `${filtered.length} MATCH`;
if (filtered.length === 0) { playlistContainer.innerHTML = ` <div style="text-align:center; padding:40px 10px; color:var(--text-muted);"> <i class="fa-solid fa-calendar-xmark fa-2x" style="color:var(--text-dim); margin-bottom:8px;"></i> <p style="font-weight:700; font-size:13px; color:#fff;">Tidak ada pertandingan saat ini</p> <p style="font-size:11.5px; color:var(--text-dim); margin-top:2px;">Silakan pilih cabang olahraga lain di menu atas.</p> </div>`; return; }
const groupOrder = ['football', 'basketball', 'badminton', 'tennis', 'volleyball', 'esports']; const groups = {}; groupOrder.forEach(k => { groups[k] = []; });
filtered.forEach(m => { const meta = getSportCategoryMeta(m.sportCategory || '', m.title || '', m.league || ''); if (!groups[meta.key]) groups[meta.key] = []; groups[meta.key].push(m); });
let fullHtml = '';
groupOrder.forEach(groupKey => { const list = groups[groupKey]; if (!list || list.length === 0) return;
const sampleMeta = getSportCategoryMeta(groupKey, '', '');
if (currentCategoryFilter === 'live' || currentCategoryFilter === 'all') { fullHtml += ` <div class="playlist-category-divider"> <div class="playlist-divider-title"> <span>${sampleMeta.icon}</span> <span>${sampleMeta.name} ${currentCategoryFilter === 'live' ? 'LIVE' : ''}</span> </div> <span class="playlist-divider-count">${list.length}</span> </div> `; }
list.forEach(match => { const globalIdx = allLoadedMatches.indexOf(match); const isLive = match.status === 1; const isFinished = match.status === 2; const homeName = match.homeTeam || match.title.split(' vs ')[0] || 'Tim 1'; const awayName = match.awayTeam || match.title.split(' vs ')[1] || 'Tim 2'; const homeLogo = match.homeLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'; const awayLogo = match.awayLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png';
let scoreBadge = ''; if (isLive) { scoreBadge = `<span class="match-row-score-badge">${match.scoreText || 'LIVE'}</span>`; } else if (isFinished) { scoreBadge = `<span class="match-row-vs-badge" style="color:var(--text-dim);">FT</span>`; } else { scoreBadge = `<span class="match-row-vs-badge">VS</span>`; }
const activeClass = (currentActiveMatch && currentActiveMatch.title === match.title) ? ' active' : '';
fullHtml += ` <div class="match-row-item${activeClass}" onclick="selectMatchCard(${globalIdx})" id="match-row-${globalIdx}"> <div class="match-row-header"> <span class="match-row-league">${match.league || 'Turnamen Olahraga'}</span> <span class="match-row-time"> ${isLive ? '<span class="live-indicator" style="padding:1px 6px; font-size:9.5px;"><i class="fa-solid fa-circle fa-2xs"></i> LIVE</span>' : '<i class="fa-regular fa-clock"></i> ' + (match.kickoffText || '')} </span> </div>
<div class="match-row-teams-grid"> <div class="team-entry"> <img src="${homeLogo}" alt="${homeName}" class="team-mini-logo" onerror="this.src='https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'"/> <span>${homeName}</span> </div>
${scoreBadge}
<div class="team-entry away"> <span>${awayName}</span> <img src="${awayLogo}" alt="${awayName}" class="team-mini-logo" onerror="this.src='https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'"/> </div> </div> </div> `; }); });
playlistContainer.innerHTML = fullHtml;
// Auto-load first match into player if not set if (!currentActiveMatch && filtered.length > 0) { setHeroMatchPreview(filtered[0]); } }
// 3. FILTER MATCHES BY SPORT (HEADER TABS CLICK) function filterMatchesBySport(category, clickedElement) { currentCategoryFilter = category;
document.querySelectorAll('.nav-item-btn').forEach(el => { el.classList.remove('active'); });
document.querySelectorAll('[data-cat="' + category + '"]').forEach(el => { el.classList.add('active'); });
if (clickedElement) { clickedElement.classList.add('active'); }
renderInteractivePlaylist(allLoadedMatches); }
// 4. SEARCH HANDLER function handleMatchSearch(keyword) { currentSearchKeyword = keyword; renderInteractivePlaylist(allLoadedMatches); }
// 5. SELECT MATCH CARD & SET PREVIEW function selectMatchCard(index) { const match = allLoadedMatches[index]; if (!match) return; setHeroMatchPreview(match); playMatchDirect(index, 1); }
function setHeroMatchPreview(match) { currentActiveMatch = match; activeStreamUrlServer1 = match.streamUrl || match.streamJalur1 || ''; activeStreamUrlServer2 = match.server2Url || match.streamJalur2 || ''; activeStreamUrlServer3 = match.streamJalur3 || match.postUrl || '';
const leagueEl = document.getElementById('playerLeagueText'); if (leagueEl) leagueEl.textContent = match.league || 'Turnamen Olahraga';
const stageLeague = document.getElementById('stageLeague'); if (stageLeague) stageLeague.textContent = match.league || 'Turnamen Olahraga';
const stageTitle = document.getElementById('stageTitle'); if (stageTitle) stageTitle.textContent = match.title;
const stageKickoff = document.getElementById('stageKickoff'); if (stageKickoff) { if (match.status === 1) { stageKickoff.innerHTML = '<b style="color:#ef4444;">🔴 PERTANDINGAN SEDANG LIVE</b>'; } else { stageKickoff.innerHTML = 'Jadwal Kick-off: <b>' + (match.kickoffText || 'Siap Tayang') + '</b>'; } }
const homeNameEl = document.getElementById('detailHomeTeam'); if (homeNameEl) homeNameEl.textContent = match.homeTeam || match.title.split(' vs ')[0] || 'Tuan Rumah';
const awayNameEl = document.getElementById('detailAwayTeam'); if (awayNameEl) awayNameEl.textContent = match.awayTeam || match.title.split(' vs ')[1] || 'Tamu';
const scoreEl = document.getElementById('detailScore'); if (scoreEl) { if (match.status === 1) scoreEl.textContent = match.scoreText || '0 - 0'; else if (match.status === 2) scoreEl.textContent = match.scoreText || 'FT'; else scoreEl.textContent = 'VS'; }
const homeLogoEl = document.getElementById('detailHomeLogo'); if (homeLogoEl) homeLogoEl.src = match.homeLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png';
const awayLogoEl = document.getElementById('detailAwayLogo'); if (awayLogoEl) awayLogoEl.src = match.awayLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png';
document.querySelectorAll('.match-row-item').forEach(el => el.classList.remove('active')); const activeEl = document.getElementById('match-row-' + allLoadedMatches.indexOf(match)); if (activeEl) activeEl.classList.add('active'); }
// 6. PLAY STREAM DIRECTLY function playMatchDirect(index, serverIndex) { const match = allLoadedMatches[index]; if (match) setHeroMatchPreview(match); activeCurrentServer = serverIndex || 1;
triggerAdsterra();
if (window.innerWidth < 1100) { const playerCard = document.getElementById('playerSection'); if (playerCard) { playerCard.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }
document.querySelectorAll('.btn-server').forEach((btn, idx) => { if (idx + 1 === activeCurrentServer) btn.classList.add('active'); else btn.classList.remove('active'); });
let targetStreamUrl = activeStreamUrlServer1; if (activeCurrentServer === 2 && activeStreamUrlServer2) targetStreamUrl = activeStreamUrlServer2; if (activeCurrentServer === 3 && activeStreamUrlServer3) targetStreamUrl = activeStreamUrlServer3;
executeStreamPlayback(targetStreamUrl, match); }
function triggerStagePlay() { if (currentActiveMatch) { const url = currentActiveMatch.streamJalur1 || currentActiveMatch.streamJalur3 || currentActiveMatch.postUrl; launchStreamWindow(url); } else if (allLoadedMatches.length > 0) { selectMatchCard(0); const url = allLoadedMatches[0].streamJalur1 || allLoadedMatches[0].streamJalur3; launchStreamWindow(url); } }
function switchServer(serverIdx) { activeCurrentServer = serverIdx; triggerAdsterra();
document.querySelectorAll('.btn-server').forEach((btn, idx) => { if (idx + 1 === activeCurrentServer) btn.classList.add('active'); else btn.classList.remove('active'); });
let targetStreamUrl = activeStreamUrlServer1; if (activeCurrentServer === 2 && activeStreamUrlServer2) targetStreamUrl = activeStreamUrlServer2; if (activeCurrentServer === 3 && activeStreamUrlServer3) targetStreamUrl = activeStreamUrlServer3;
if (currentActiveMatch) { launchStreamWindow(targetStreamUrl); } }
// 7. ROBUST THEATER POPUP & VIDEO PLAYBACK ENGINE (NO REFUSED TO CONNECT) function launchStreamWindow(streamUrl) { triggerAdsterra(); const targetUrl = streamUrl || (currentActiveMatch ? (currentActiveMatch.streamJalur1 || currentActiveMatch.streamJalur3) : window.location.href);
// Buka theater window murni beresolusi tinggi tanpa batasan X-Frame-Options const playerWin = window.open(targetUrl, 'MeiwaSportsStream', 'width=1180,height=680,resizable=yes,scrollbars=yes,status=no'); if (!playerWin || playerWin.closed || typeof playerWin.closed === 'undefined') { // Fallback jika popup blocker aktif window.open(targetUrl, '_blank', 'noopener,noreferrer'); } }
function executeStreamPlayback(streamUrl, match) { const video = document.getElementById('mainVideoPlayer'); const iframe = document.getElementById('mainIframePlayer'); const stage = document.getElementById('playerStage');
if (hlsInstance) { hlsInstance.destroy(); hlsInstance = null; } if (flvPlayerInstance) { flvPlayerInstance.destroy(); flvPlayerInstance = null; }
const isDirectFlv = streamUrl && (streamUrl.endsWith('.flv') || streamUrl.includes('.flv?')); const isDirectM3u8 = streamUrl && (streamUrl.endsWith('.m3u8') || streamUrl.includes('.m3u8?'));
if (isDirectFlv && typeof flvjs !== 'undefined' && flvjs.isSupported()) { if (stage) stage.style.display = 'none'; if (iframe) iframe.style.display = 'none'; if (video) { video.style.display = 'block'; try { flvPlayerInstance = flvjs.createPlayer({ type: 'flv', url: streamUrl, isLive: true, cors: true }); flvPlayerInstance.attachMediaElement(video); flvPlayerInstance.load(); video.play().catch(() => {}); return; } catch (e) { console.warn('FLV fallback:', e); } } }
if (isDirectM3u8 && typeof Hls !== 'undefined' && Hls.isSupported()) { if (stage) stage.style.display = 'none'; if (iframe) iframe.style.display = 'none'; if (video) { video.style.display = 'block'; try { hlsInstance = new Hls({ enableWorker: true, lowLatencyMode: true }); hlsInstance.loadSource(streamUrl); hlsInstance.attachMedia(video); hlsInstance.on(Hls.Events.MANIFEST_PARSED, function() { video.play().catch(() => {}); }); return; } catch (e) { console.warn('HLS fallback:', e); } } }
// Default: Pastikan Stage tetap interaktif dan siap diputar dengan 1-klik if (stage) stage.style.display = 'flex'; if (video) { video.pause(); video.style.display = 'none'; } if (iframe) { iframe.style.display = 'none'; } }
function openCurrentMatchNewTab() { triggerAdsterra(); if (currentActiveMatch) { const url = currentActiveMatch.streamJalur1 || currentActiveMatch.streamJalur3 || currentActiveMatch.postUrl || window.location.href; launchStreamWindow(url); } }
function shareCurrentMatch() { if (navigator.share && currentActiveMatch) { navigator.share({ title: currentActiveMatch.title + ' - Live Streaming MeiwaSports', url: window.location.href }).catch(() => {}); } else { navigator.clipboard.writeText(window.location.href); alert('Link siaran pertandingan berhasil disalin!'); } }
// 8. REAL-TIME MATCHES SYNC function fetchLiveMatchesDirect() { const syncSources = [ 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/matches.json', 'https://cdn.jsdelivr.net/gh/adityafarid0112/meiwatv@main/matches.json' ];
function tryFetchSource(idx) { if (idx >= syncSources.length) return; fetch(syncSources[idx] + '?_t=' + Date.now()) .then(res => { if (!res.ok) throw new Error('Sync source failed'); return res.json(); }) .then(data => { if (Array.isArray(data) && data.length > 0) { allLoadedMatches = data; renderInteractivePlaylist(allLoadedMatches); } }) .catch(() => { tryFetchSource(idx + 1); }); }
tryFetchSource(0); }
// 9. INIT ON DOM LOAD function initLivePortal() { renderInteractivePlaylist(AUTO_LIVE_DATASET);
setTimeout(function() { fetchLiveMatchesDirect(); setInterval(fetchLiveMatchesDirect, 120000); }, 4000); }
document.addEventListener('DOMContentLoaded', initLivePortal); //
